@extends('layout') @section('title','Calendrier') @section('subtitle','Organisez les temps d’échange et les prochaines séances.') @section('content')<section class="panel form-panel"><h2>Rendez-vous</h2>@forelse($appointments as $a)<div class="list-row"><div class="date-tile"><strong>{{ $a->starts_at->format('d') }}</strong><span>{{ $a->starts_at->locale('fr')->isoFormat('MMM') }}</span></div><div class="grow"><strong>{{ $a->title }}</strong><small>{{ $a->client->full_name }} · {{ $a->starts_at->format('d/m/Y à H:i') }} · {{ $a->duration }} min · {{ $a->location }}</small></div>@include('partials.status',['status'=>$a->status])@if(auth()->user()->isProfessional() && $a->status==='planifie')<form method="post" action="/calendrier/{{ $a->id }}/annuler">@csrf<button class="btn danger small">Annuler</button></form>@endif</div>@empty<p class="empty">Aucun rendez-vous.</p>@endforelse{{ $appointments->links('partials.pagination') }}</section>@if(auth()->user()->isProfessional())<section class="panel form-panel"><h2>Planifier un rendez-vous</h2><form method="post" action="/calendrier">@csrf<div class="form-grid"><label>Patient<select name="client_id" required>@foreach($clients as $c)<option value="{{ $c->id }}">{{ $c->full_name }}</option>@endforeach</select></label><label>Objet<input name="title" required maxlength="200" value="{{ old('title','Séance de suivi') }}"></label><label>Date et heure<input name="starts_at" type="datetime-local" required value="{{ old('starts_at') }}"></label><label>Durée (minutes)<input name="duration" type="number" min="15" max="480" value="60" required></label><label>Lieu<input name="location" maxlength="255" placeholder="Cabinet, visioconférence…"></label></div><button class="btn primary">Planifier</button></form></section>@endif @endsection